<?php
require_once __DIR__ . '/bootstrap.php';
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!hash_equals($_SESSION['csrf'], $_POST['_csrf'] ?? '')) $error = 'La sesión expiró. Recarga la página.';
    else { $email = trim($_POST['email'] ?? ''); $password = $_POST['password'] ?? ''; if (isset($conn) && !$conn->connect_error) { $stmt=$conn->prepare('SELECT id,username,email,password,role FROM users WHERE email=? AND status="active" LIMIT 1'); $stmt->bind_param('s',$email); $stmt->execute(); $user=$stmt->get_result()->fetch_assoc(); if($user && password_verify($password,$user['password'])) { unset($user['password']); $_SESSION['user']=$user; $_SESSION['user_id']=$user['id']; header('Location: index.php'); exit; } } $error='Correo o contraseña incorrectos.'; }
}
